  5→	import { onMount, onDestroy } from 'svelte';
  6→	import type { PlanSummary } from '@kynetic-ai/shared';
  7→	import { fetchPlans } from '$lib/api';
  8→	import { isStaticMode } from '$lib/stores/mode.svelte';
  9→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 10→	import { getProjectVersion } from '$lib/stores/project.svelte';
 11→	import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
 12→	import { Badge } from '$lib/components/ui/badge';
 13→	import MapIcon from '@lucide/svelte/icons/map';
 14→
 15→	// ── Data state ──
 16→	let plans = $state<PlanSummary[]>([]);
 17→	let loading = $state(true);
 18→	let error = $state('');
 19→
 20→	// ── Filter state ──
 21→	type PlanStatusFilter = 'all' | 'draft' | 'approved' | 'active' | 'completed' | 'rejected';
 22→	let filterStatus = $state<PlanStatusFilter>('all');
 23→
 24→	// ── Plan status labels and colors ──
 25→	// AC: @ui-plans-view ac-1 — visually distinct statuses with text labels
 26→	const PLAN_STATUS_LABELS: Record<string, string> = {
 27→		draft: 'Draft',
 28→		approved: 'Approved',
 29→		active: 'Active',
 30→		completed: 'Completed',
 31→		rejected: 'Rejected'
 32→	};
 33→
 34→	const PLAN_STATUS_COLORS: Record<string, string> = {
 35→		draft: 'bg-status-pending text-status-pending-fg',
 36→		approved: 'bg-status-pending-review text-status-pending-review-fg',
 37→		active: 'bg-status-in-progress text-status-in-progress-fg',
 38→		completed: 'bg-status-completed text-status-completed-fg',
 39→		rejected: 'bg-status-blocked text-status-blocked-fg'
 40→	};
 41→
 42→	// ── Filtered plans ──
 43→	let filteredPlans = $derived.by(() => {
 44→		if (filterStatus === 'all') return plans;
 45→		return plans.filter((p) => p.status === filterStatus);
 46→	});
 47→
 48→	// ── Status summary counts ──
 49→	let statusCounts = $derived.by(() => {
 50→		const counts: Record<string, number> = {};
 51→		for (const plan of plans) {
 52→			counts[plan.status] = (counts[plan.status] ?? 0) + 1;
 53→		}
 54→		return counts;
 55→	});
 56→
 57→	// ── Lifecycle ──
 58→	onMount(async () => {
 59→		await loadData();
 60→
 61→		if (!isStaticMode()) {
 62→			subscribe(['plans:updates']);
 63→			on('plans:updates', handleUpdate);
 64→		}
 65→	});
 66→
 67→	onDestroy(() => {
 68→		if (!isStaticMode()) {
 69→			off('plans:updates', handleUpdate);
 70→			unsubscribe(['plans:updates']);
 71→		}
 72→	});
 73→
 74→	// Reload on project change
 75→	$effect(() => {
 76→		const version = getProjectVersion();
 77→		if (version > 0) {
 78→			loadData();
 79→		}
 80→	});
 81→
 82→	// ── Data loading ──
 83→	async function loadData() {
 84→		try {
 85→			loading = true;
 86→			error = '';
 87→			const response = await fetchPlans();
 88→			plans = response.items;
 89→		} catch (err) {
 90→			error = err instanceof Error ? err.message : 'Failed to load plans';
 91→		} finally {
 92→			loading = false;
 93→		}
 94→	}
 95→
 96→	// ── WebSocket handler ──
 97→	function handleUpdate() {
 98→		loadData();
 99→	}
100→
101→	// ── Formatting ──
102→	function formatDate(dateString: string): string {
103→		const date = new Date(dateString);
104→		const now = new Date();
105→		const diffMs = now.getTime() - date.getTime();
106→		const diffMins = Math.floor(diffMs / 60000);
107→		const diffHours = Math.floor(diffMs / 3600000);
108→		const diffDays = Math.floor(diffMs / 86400000);
109→
110→		if (diffMins < 1) return 'just now';
111→		if (diffMins < 60) return `${diffMins}m ago`;
112→		if (diffHours < 24) return `${diffHours}h ago`;
113→		if (diffDays < 7) return `${diffDays}d ago`;
114→
115→		return date.toLocaleDateString();
116→	}
117→
118→	// AC: @ui-plans-view ac-1 — Progress percentage from task completion status
119→	function progressPercent(plan: PlanSummary): number {
120→		if (plan.task_progress.total === 0) return 0;
121→		return Math.round((plan.task_progress.completed / plan.task_progress.total) * 100);
122→	}
123→</script>
124→
125→<div class="flex flex-col gap-4 p-6">
126→	<!-- Header -->
127→	<div class="flex items-center justify-between">
128→		<div>
129→			<h1 class="text-2xl font-bold">Plans</h1>
130→			{#if !loading}
131→				<p class="text-sm text-muted-foreground" data-testid="plans-summary">
132→					{plans.length} plan{plans.length === 1 ? '' : 's'}
133→					{#if Object.keys(statusCounts).length > 0}
134→						&middot;
135→						{#each Object.entries(statusCounts) as [status, count], i}
136→							{count} {PLAN_STATUS_LABELS[status]?.toLowerCase() ?? status}{i < Object.entries(statusCounts).length - 1 ? ', ' : ''}
137→						{/each}
138→					{/if}
139→					{#if filteredPlans.length !== plans.length}
140→						&middot; Showing {filteredPlans.length} filtered
141→					{/if}
142→				</p>
143→			{/if}
144→		</div>
145→	</div>
146→
147→	<!-- Filter controls -->
148→	<div class="flex flex-wrap gap-2 items-center" data-testid="plans-filters">
149→		<select
150→			bind:value={filterStatus}
151→			class="rounded-md border bg-background px-3 py-1.5 text-sm"
152→			data-testid="plans-status-filter"
153→		>
154→			<option value="all">All Status</option>
155→			<option value="draft">Draft</option>
156→			<option value="approved">Approved</option>
157→			<option value="active">Active</option>
158→			<option value="completed">Completed</option>
159→			<option value="rejected">Rejected</option>
160→		</select>
161→	</div>
162→
163→	{#if error}
164→		<div class="bg-destructive/10 text-destructive p-4 rounded-lg text-sm" data-testid="error-message" role="alert">
165→			{error}
166→		</div>
167→	{/if}
168→
169→	<!-- Plans list -->
170→	{#if loading}
171→		<div class="space-y-2" data-testid="plans-loading">
172→			{#each Array(3) as _}
173→				<div class="h-28 rounded-lg bg-muted ds-shimmer"></div>
174→			{/each}
175→		</div>
176→	{:else if filteredPlans.length === 0}
177→		<div class="flex flex-col items-center justify-center py-16" data-testid="plans-empty">
178→			<MapIcon class="size-12 text-muted-foreground/30 mb-4" />
179→			{#if plans.length === 0}
180→				<h2 class="text-lg font-medium text-muted-foreground mb-1">No plans yet</h2>
181→				<p class="text-sm text-muted-foreground">
182→					{#if isStaticMode()}
183→						No plan data available in the snapshot.
184→					{:else}
185→						Create plans with <code class="text-xs bg-muted px-1 py-0.5 rounded">kspec plan add</code> to track implementation progress.
186→					{/if}
187→				</p>
188→			{:else}
189→				<h2 class="text-lg font-medium text-muted-foreground mb-1">No matching plans</h2>
190→				<p class="text-sm text-muted-foreground">Try adjusting the filter above.</p>
191→			{/if}
192→		</div>
193→	{:else}
194→		<div class="flex flex-col gap-3" data-testid="plans-list">
195→			{#each filteredPlans as plan (plan._ulid)}
196→				<!-- AC: @ui-plans-view ac-1 — Plan card with all required fields -->
197→				<Card class="transition-all duration-200 hover:shadow-md" data-testid="plan-card">
198→					<CardHeader class="pb-3">
199→						<div class="flex items-start justify-between gap-4">
200→							<div class="flex-1 min-w-0">
201→								<div class="flex items-center gap-2 mb-1">
202→									<Badge
203→										class={PLAN_STATUS_COLORS[plan.status] ?? 'bg-muted text-muted-foreground'}
204→										data-testid="plan-status"
205→									>
206→										{PLAN_STATUS_LABELS[plan.status] ?? plan.status}
207→									</Badge>
208→									<h3 class="text-sm font-semibold truncate" data-testid="plan-title">{plan.title}</h3>
209→								</div>
210→							</div>
211→						</div>
212→					</CardHeader>
213→					<CardContent class="pt-0">
214→						<div class="flex flex-col gap-3">
215→							<!-- AC: @ui-plans-view ac-1 — Progress bar based on task completion status -->
216→							{#if plan.task_progress.total > 0}
217→								<div class="flex items-center gap-3">
218→									<div class="flex-1 h-2 rounded-full bg-muted overflow-hidden" data-testid="plan-progress-bar">
219→										<div
220→											class="h-full rounded-full transition-all duration-300 bg-[var(--design-status-completed)]"
221→											style="width: {progressPercent(plan)}%"
222→										></div>
223→									</div>
224→									<span class="text-xs font-medium text-muted-foreground whitespace-nowrap" data-testid="plan-progress-text">
225→										{progressPercent(plan)}% ({plan.task_progress.completed}/{plan.task_progress.total} tasks)
226→									</span>
227→								</div>
228→								<!-- Task status breakdown -->
229→								<div class="flex flex-wrap gap-2 text-xs text-muted-foreground" data-testid="plan-task-breakdown">
230→									{#if plan.task_progress.completed > 0}
231→										<span class="inline-flex items-center gap-1">
232→											<span class="inline-block size-2 rounded-full bg-[var(--design-status-completed)]"></span>
233→											{plan.task_progress.completed} completed
234→										</span>
235→									{/if}
236→									{#if plan.task_progress.in_progress > 0}
237→										<span class="inline-flex items-center gap-1">
238→											<span class="inline-block size-2 rounded-full bg-[var(--design-status-in-progress)]"></span>
239→											{plan.task_progress.in_progress} in progress
240→										</span>
241→									{/if}
242→									{#if plan.task_progress.pending > 0}
243→										<span class="inline-flex items-center gap-1">
244→											<span class="inline-block size-2 rounded-full bg-[var(--design-status-pending)]"></span>
245→											{plan.task_progress.pending} pending
246→										</span>
247→									{/if}
248→									{#if plan.task_progress.blocked > 0}
249→										<span class="inline-flex items-center gap-1">
250→											<span class="inline-block size-2 rounded-full bg-[var(--design-status-blocked)]"></span>
251→											{plan.task_progress.blocked} blocked
252→										</span>
253→									{/if}
254→								</div>
255→							{/if}
256→
257→							<!-- Metadata row -->
258→							<div class="flex items-center gap-2 text-xs text-muted-foreground">
259→								<span data-testid="plan-created-at">{formatDate(plan.created_at)}</span>
260→								<span>&middot;</span>
261→								<span data-testid="plan-spec-count">{plan.spec_count} spec{plan.spec_count === 1 ? '' : 's'}</span>
262→								<span>&middot;</span>
263→								<span data-testid="plan-task-count">{plan.task_count} task{plan.task_count === 1 ? '' : 's'}</span>
264→								{#if plan.slugs.length > 0}
265→									<span>&middot;</span>
266→									<code class="text-xs bg-muted px-1 py-0.5 rounded" data-testid="plan-slug">@{plan.slugs[0]}</code>
267→								{/if}
268→							</div>
269→						</div>
270→					</CardContent>
271→				</Card>
272→			{/each}
273→		</div>
274→	{/if}
275→</div>
