   111→		const diffMs = now.getTime() - date.getTime();
   112→		const diffMins = Math.floor(diffMs / 60000);
   113→		const diffHours = Math.floor(diffMs / 3600000);
   114→		const diffDays = Math.floor(diffMs / 86400000);
